entries[241611] = { ["name"] = "Zarat's Head", ["text"] = "Quest Item\n\"Looks more like a large flower than a head.\"" }
entries[241612] = { ["name"] = "Lightwood Javelin", ["text"] = "Quest Item\n\"The javelin you created with Woodcrafter Azai's guidance. With his expert teaching, the weapon turned out to be quite beautiful.\"" }
entries[241614] = { ["name"] = "Old Amani Pot", ["text"] = "Quest Item\n\"Paint has long flaked off this pot and a few of the gems are chipped.\"" }
entries[241615] = { ["name"] = "Lost Amani Trinket", ["text"] = "Quest Item\n\"The material is scuffed, but the color is quite exquisite.\"" }
entries[241616] = { ["name"] = "The Underpin", ["text"] = "Requires level 70 to 80 ( 80)\n\"Defeating The Underpin may reward equipment, recipes, currencies, collectibles, and curios.\"" }
entries[241617] = { ["name"] = "Elegant Padded Chair", ["text"] = "1\nHousing Decor\nBinds to Warband\nUse: This Decor will be added immediately on purchase to your House Chest.\nSell Price:" }
