entries[241622] = { ["name"] = "Ornate Weapon Rack", ["text"] = "3\nHousing Decor\nBinds to Warband\nUse: This Decor will be added immediately on purchase to your House Chest.\nSell Price:" }
entries[241623] = { ["name"] = "Elegant Elven Barrel", ["text"] = "1\nHousing Decor\nBinds to Warband\nUse: Add this Decor to your House Chest.\nSell Price:" }
entries[241632] = { ["name"] = "Heroic Waxy Figurine", ["text"] = "Binds when picked up\n\"A carefully carved and sculpted wax blob that Skibbles made to resemble you. It's clear she worked very hard on it, even though it's hard to tell where the face is.\"\nSell Price:" }
entries[241633] = { ["name"] = "Tiny Decorative Rocket", ["text"] = "Binds when picked up\n\"When the little crank is wound, the miniature tin rocket makes a faint whirring sound and a wooden exhaust flame gently spins. A simple depiction of a small nerubian and a stick figure is scratched into one of the rocket fins.\"\nSell Price:" }
entries[241635] = { ["name"] = "Patchy Spider-Silk Square", ["text"] = "Binds when picked up\n\"This small poorly woven square seems to depict both nerubian and Arathi-inspired patterns. It has your initials crudely stitched in one corner.\"\nSell Price:" }
entries[241636] = { ["name"] = "Storm Glass and Feather Necklace", ["text"] = "Binds when picked up\n\"One single electric blue stormrook feather dangles gently between two fragments of Storm Glass. A small, rusty Undermine minted nut and bolt act as the clasp.\"\nSell Price:" }
