entries[242390] = { ["name"] = "Shadowgraft Fragment", ["text"] = "Quest Item\n\"The strange metal of these cuff-like fragments thrum with Void energy. Holding it, your heart races. You long for the thrill of battle.\"" }
entries[242391] = { ["name"] = "Soulbinder's Embrace", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+21 [Agility or Strength]\nUse: Activate the Soulshield to unleash a shockwave dealing 282 Arcane damage to all nearby enemies and reduce your damage taken by 50% for 20 sec or until 9883 damage has been prevented. (1 Min Cooldown)\nDefeat Soulbinder Naazindhri in Manaforge Omega on Normal or higher difficulty.\nDefeat Soulbinder Naazindhri in Manaforge Omega on Mythic difficulty.\nSell Price:" }
entries[242392] = { ["name"] = "Diamantine Voidcore", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 32 Mastery\nEquip: Your spells have a chance to empower the Voidcore, granting you 29 Intellect for 15 sec. This chance is increased by 25% while below 25% mana. Multiple applications may overlap.\nDefeat Fractillus in Manaforge Omega on Normal or higher difficulty.\nDefeat Fractillus in Manaforge Omega on Mythic difficulty.\n\nShards of the Void (0/4)\nVoidglass Spire\nDiamantine Voidcore\nVoidglass Kris\nVoidglass Sovereign's Blade\n(2) Set : While Diamantine Voidcore is empowered, your voidglass shards are 200% more effective.\nSell Price:" }
entries[242393] = { ["name"] = "Loom'ithar's Living Silk", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 32 Haste\nUse: Weave an arcane cocoon around yourself and four nearby allies for 10 sec, reducing their damage taken by 75% until 16147 damage has been prevented.\n\nIf a cocoon expires, it bursts to heal an injured ally for 50% of its remaining power. (1 Min, 30 Sec Cooldown)\nDefeat Loom'ithar in Manaforge Omega on Normal or higher difficulty.\nDefeat Loom'ithar in Manaforge Omega on Mythic difficulty.\nSell Price:" }
entries[242394] = { ["name"] = "Eradicating Arcanocore", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+21 Strength\nEquip: Your attacks have a high chance to charge the Arcanocore. At 10 charges, deploy a sentinel to arcanoblast your target for ( 6916 * 1 ) Arcane damage split between nearby enemies. Recover 2 charges if only one enemy is struck.\n\nDamage increased by 30% per additional enemy, up to 150%.\nDefeat the Plexus Sentinel in Manaforge Omega on Normal or higher difficulty.\nDefeat the Plexus Sentinel in Manaforge Omega on Mythic difficulty.\nSell Price:" }
entries[242395] = { ["name"] = "Astral Antenna", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+21 [Agility or Strength or Intellect]\nEquip: The antenna has a chance to detect and draw ambient arcane energy towards you, granting 94 Critical Strike for 10 sec. Multiple applications may overlap.\nDefeat Loom'ithar in Manaforge Omega on Normal or higher difficulty.\nDefeat Loom'ithar in Manaforge Omega on Mythic difficulty.\nSell Price:" }
entries[242396] = { ["name"] = "Unyielding Netherprism", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nEquip: Your harmful abilities draw focused void through the prism to deal ( 847 * 1 ) Cosmic damage split between your target and nearby enemies. Damage increased by 30% per enemy struck, up to 150%. This effect may occur every 10 sec and accumulates Latent Power within the prism, up to 18 times. (10s cooldown)\nUse: Consume all Latent Power to gain 10 Strength or Agility per stack for 20 sec. (20 Sec Cooldown)\nDefeat Fractillus in Manaforge Omega on Normal or higher difficulty.\nDefeat Fractillus in Manaforge Omega on Mythic difficulty.\nSell Price:" }
entries[242397] = { ["name"] = "Sigil of the Cosmic Hunt", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+21 Agility\nEquip: Your attacks have a high chance to unleash a cosmic onslaught, dealing ( 994 * 1 ) Cosmic damage to your target.\n\nDamage increased by 2% for every 1% health the target is missing, and nearby enemies take 50% of the damage dealt split between them.\nDefeat the Soul Hunters in Manaforge Omega on Normal or higher difficulty.\nDefeat the Soul Hunters in Manaforge Omega on Mythic difficulty.\nSell Price:" }
entries[242398] = { ["name"] = "Naazindhri's Mystic Lash", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+21 Intellect\nEquip: Your damaging spells have a high chance to lash your target with arcane power, dealing ( 1238 * 1 ) Arcane damage split between your target and enemies caught in its path.\n\nDamage increased by 30% per additional enemy, up to 150%, and further increased by your Mastery.\nDefeat Soulbinder Naazindhri in Manaforge Omega on Normal or higher difficulty.\nDefeat Soulbinder Naazindhri in Manaforge Omega on Mythic difficulty.\nSell Price:" }
entries[242399] = { ["name"] = "Screams of a Forgotten Sky", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 32 Critical Strike\nEquip: Your harmful spells and abilities have a chance to strike your target with an abyssal comet, dealing ( 6362 * 1 ) Cosmic damage and amplifying their gravity to increase the damage of future comets by 5%.\n\nUpon death, enemies implode to deal 5081 Cosmic damage per gravity stack split between nearby enemies. Damage increased by 30% per additional enemy, up to 150%.\nDefeat Dimensius in Manaforge Omega on Normal or higher difficulty.\nDefeat Dimensius in Manaforge Omega on Mythic difficulty.\nSell Price:" }
entries[242400] = { ["name"] = "Nexus-King's Command", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 32 Mastery\nEquip: Become Oath-Bound to a nearby ally every 30 sec.\n\nDirectly healing the ally fulfills the oath to grant you 52 Intellect for 12 sec and shields your ally for 100% of any overhealing done.\nDefeat Nexus-King Salhadaar in Manaforge Omega on Normal or higher difficulty.\nDefeat Nexus-King Salhadaar in Manaforge Omega on Mythic difficulty.\nSell Price:" }
entries[242401] = { ["name"] = "Brand of Ceaseless Ire", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 32 Critical Strike\nEquip: Taking damage infuriates you, causing you to absorb 298 damage and deal 682 Shadow damage per infuriation split between nearby enemies. Damage increased by 30% per additional enemy, up to 150%.\n\nYou may be further infuriated every 15 sec, stacking up to 15 times, but calm quickly upon leaving combat.\n\nValid only for tank specializations. (15s cooldown)\nDefeat the Soul Hunters in Manaforge Omega on Normal or higher difficulty.\nDefeat the Soul Hunters in Manaforge Omega on Mythic difficulty.\nSell Price:" }
entries[242402] = { ["name"] = "Araz's Ritual Forge", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 32 Critical Strike\nUse: Recklessly feed a portion of your essence to the forge, granting you 104 Primary Stat decaying over 30 sec at the cost of 15% of your maximum health. (2 Min Cooldown)\nDefeat Forgeweaver Araz in Manaforge Omega on Normal or higher difficulty.\nDefeat Forgeweaver Araz in Manaforge Omega on Mythic difficulty.\nSell Price:" }
entries[242403] = { ["name"] = "Perfidious Projector", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 32 Haste\nUse: Compel an oathbound Shadowguard squad to annihilate your target and nearby enemies, dealing 40984 Cosmic damage split between them.\n\nDamage increased by 30% per additional enemy, up to 150%. (2 Min Cooldown)\nDefeat Nexus-King Salhadaar in Manaforge Omega on Normal or higher difficulty.\nDefeat Nexus-King Salhadaar in Manaforge Omega on Mythic difficulty.\nSell Price:" }
entries[242404] = { ["name"] = "All-Devouring Nucleus", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 32 Versatility\nEquip: Taking damage has a high chance to cause you to devour the essence of nearby enemies, dealing 3130 Shadow damage split between them and healing you for 150% of the damage dealt.\n\nFatal damage not exceeding 10311 instead restores you to 20% health and reconstitutes you as unstable void for 6 sec. Exceed 50% health to stabilize and avoid death. This effect may occur once per 8 min. The Nucleus is unable to deal damage while recharging.\nDefeat Dimensius in Manaforge Omega on Normal or higher difficulty.\nDefeat Dimensius in Manaforge Omega on Mythic difficulty.\nSell Price:" }
entries[242405] = { ["name"] = "Band of the Shattered Soul", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+55 Stamina\n+ 11 Critical Strike\n+ 65 Haste\nEquip: The powers of your Reshii Wraps also reduce Cosmic damage taken by 50% for 20 sec or until 1710 damage has been prevented.\nDefeat Dimensius in Manaforge Omega on Normal or higher difficulty.\nDefeat Dimensius in Manaforge Omega on Mythic difficulty.\nSell Price:" }
entries[242406] = { ["name"] = "Salhadaar's Folly", ["text"] = "Binds when picked up\nNeck\n+55 Stamina\n+ 11 Critical Strike\n+ 65 Mastery\nSell Price:" }
